// Copies the classic 2D maps (../maps/*.js, plain browser scripts that push onto
// window.MAPS) into ES modules under src/maps/classic/. Run after changing a 2D map:
//   node scripts/sync-maps.mjs
import { readFile, writeFile, readdir } from 'node:fs/promises';
import path from 'node:path';
import { root } from './build.mjs';
const from = path.join(root, '..', 'maps'),
  to = path.join(root, 'src', 'maps', 'classic');
for (const name of (await readdir(from)).filter((f) => f.endsWith('.js'))) {
  const code = await readFile(path.join(from, name), 'utf8');
  const out =
    '// Generated by scripts/sync-maps.mjs from maps/' +
    name +
    ' — edit the original.\n' +
    '/* eslint-disable */\nconst window = { MAPS: [] };\nconst MAPS = window.MAPS;\n' +
    code +
    '\nexport default MAPS[0];\n';
  await writeFile(path.join(to, name.replace(/\.js$/, '.mjs')), out);
  console.log('maps/' + name + ' → src/maps/classic/' + name.replace(/\.js$/, '.mjs'));
}
